//! Per-platform build/runtime configuration.
//!
//! Generated by `cargo xtask regen-sys` from `gneiss-sys/vendor/platforms.json`
//! (upstream `tools/pebble_sdk_platform.py`; see `vendor/UPSTREAM` for the
//! snapshot's commit) and the `pebble_process_info.h` bindings.
//! Do not hand-edit: see `xtask/src/platform_table.rs`
#![allow(clippy::pedantic)]
use crate::{Platform, pebble_process_info::Version};
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum DisplayShape {
	Rect,
	Round,
}
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct Display {
	pub width:  u16,
	pub height: u16,
	pub shape:  DisplayShape,
}
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct Capabilities {
	/// `false` means BW (`PBL_BW`); `true` means color (`PBL_COLOR`).
	pub color:            bool,
	pub microphone:       bool,
	pub smartstrap:       bool,
	/// Implies `smartstrap`. `PBL_SMARTSTRAP_POWER`.
	pub smartstrap_power: bool,
	pub health:           bool,
	pub compass:          bool,
	pub touch:            bool,
	pub rgb_backlight:    bool,
	pub speaker:          bool,
}
#[derive(Debug, Clone, Copy)]
pub struct PlatformConfig {
	/// Upper-case canonical name, e.g. `"EMERY"`.
	pub name: &'static str,
	/// The applib version this platform's firmware knows, from its own
	/// `pebble_process_info.h`. An app header claiming a newer one is
	/// rejected at install, so the frozen watches sit below the current
	/// SDK's.
	pub sdk_version: Version,
	/// Raw `N` from `PROCESS_INFO_PLATFORM_<NAME> = N << 6`. The OS shifts it
	/// into position; we store the unshifted value to make the relationship
	/// explicit at use-time.
	pub process_info_platform_bit: u8,
	pub max_app_binary_size: u32,
	/// Becomes `LENGTH` of the `APP` memory region in the app linker script.
	pub max_app_memory_size: u32,
	pub max_worker_memory_size: u32,
	pub max_resources_size: u32,
	pub max_resources_size_appstore: u32,
	pub max_font_glyph_size: u16,
	pub display: Display,
	/// `Some(rev)` only for legacy platforms whose ABI is frozen.
	/// Mirrors the presence of `PBL_SDK_FROZEN` in `defines`.
	pub frozen_at_revision: Option<u32>,
	/// Bare define names, ready for `-D` prefixing. Includes the platform
	/// name (`PBL_PLATFORM_<NAME>`), color/shape (`PBL_COLOR`|`PBL_BW`,
	/// `PBL_RECT`|`PBL_ROUND`), capability flags, `PBL_DISPLAY_WIDTH=<n>` /
	/// `PBL_DISPLAY_HEIGHT=<n>`, and `PBL_SDK_FROZEN` where applicable.
	/// `PBL_SDK_3` is universal and is added by the consumer (xtask), not here.
	pub defines: &'static [&'static str],
	/// Upstream's resource tags for this platform: the platform name, colour
	/// depth, shape, capabilities and dimensions. A resource file suffixed
	/// `~<tag>` applies to the platforms carrying that tag.
	pub tags: &'static [&'static str],
	/// `defines` lowercased, minus the `NAME=value` ones: the cfg flags a
	/// build script sets for this platform (`cargo::rustc-cfg=pbl_touch`).
	/// [`ALL_CFGS`] is the matching `check-cfg` vocabulary.
	pub cfgs: &'static [&'static str],
	pub capabilities: Capabilities,
}
