/// Every cfg flag any platform sets, for a build script's
/// `cargo::rustc-check-cfg` lines. A flag the current platform does not
/// set still needs declaring, or `#[cfg]` on it warns under
/// `unexpected_cfgs`.
pub const ALL_CFGS: &[&str] = &[
	"pbl_bw",
	"pbl_color",
	"pbl_compass",
	"pbl_health",
	"pbl_microphone",
	"pbl_platform_aplite",
	"pbl_platform_basalt",
	"pbl_platform_chalk",
	"pbl_platform_diorite",
	"pbl_platform_emery",
	"pbl_platform_flint",
	"pbl_platform_gabbro",
	"pbl_rect",
	"pbl_rgb_backlight",
	"pbl_round",
	"pbl_sdk_frozen",
	"pbl_smartstrap",
	"pbl_smartstrap_power",
	"pbl_speaker",
	"pbl_touch",
];
impl Platform {
	pub const fn config(self) -> &'static PlatformConfig {
		match self {
			Platform::Aplite => &PLATFORM_APLITE,
			Platform::Basalt => &PLATFORM_BASALT,
			Platform::Chalk => &PLATFORM_CHALK,
			Platform::Diorite => &PLATFORM_DIORITE,
			Platform::Emery => &PLATFORM_EMERY,
			Platform::Flint => &PLATFORM_FLINT,
			Platform::Gabbro => &PLATFORM_GABBRO,
		}
	}
}
